<?php

declare(strict_types=1);

namespace PHPCrypt\Tests;

use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Group;
use PHPUnit\Framework\TestCase;
use PHPCrypt\Encryptor;
use PHPCrypt\JasyptEncryptor;
use PHPCrypt\JasyptStrongEncryptor;

/**
 * Cross-language compatibility against GoCrypt, the family's reference
 * implementation.
 *
 * tests/fixtures/gocrypt_vectors.json was produced by GoCrypt v1.0.0 (it is the
 * fixture RustCrypt uses, generated by RustCrypt's scripts/gen-vectors):
 *
 *  - "vectors": values GoCrypt encrypted with random salts. PHPCrypt must
 *    decrypt every one of them.
 *  - "fixed": values computed with a fixed salt and nonce. PHPCrypt must
 *    reproduce every one of them byte for byte, which proves that what
 *    PHPCrypt writes is what GoCrypt writes.
 *
 * Round trips inside one library cannot catch a wrong format, because both
 * sides are wrong in the same way. These tests can.
 */
#[Group('interop')]
class GoldenVectorTest extends TestCase
{
    use DesAvailability;

    /** @return array<string, mixed> */
    private static function fixture(): array
    {
        static $fixture = null;

        return $fixture ??= json_decode(
            (string) file_get_contents(__DIR__ . '/fixtures/gocrypt_vectors.json'),
            true,
            512,
            JSON_THROW_ON_ERROR
        );
    }

    private static function password(): string
    {
        return self::fixture()['password'];
    }

    /** Calls a private method; see the "@internal" seams in src/. */
    private static function callPrivate(object $object, string $method, mixed ...$args): mixed
    {
        return (new \ReflectionMethod($object, $method))->invoke($object, ...$args);
    }

    private static function label(string $text): string
    {
        return mb_strlen($text) > 24 ? mb_substr($text, 0, 21) . '...' : $text;
    }

    // ════════════════════════════════════════════════════════════════════════
    // Fixture sanity
    // ════════════════════════════════════════════════════════════════════════

    public function testFixtureComesFromGoCrypt(): void
    {
        $fixture = self::fixture();

        $this->assertSame('github.com/farizfadian/gocrypt v1.0.0', $fixture['gocrypt_module']);
        $this->assertSame(40, strlen($fixture['gocrypt_commit']), 'full gocrypt commit hash');
        $this->assertCount(12, $fixture['vectors'], 'three modes, four plaintexts');
    }

    public function testFixtureCoversAllModesAndPlaintexts(): void
    {
        foreach (['default', 'jasypt', 'jasypt-strong'] as $mode) {
            $plaintexts = [];
            foreach (self::fixture()['vectors'] as $vector) {
                if ($vector['mode'] === $mode) {
                    $plaintexts[] = $vector['plaintext'];
                }
            }

            $this->assertContains('hello', $plaintexts, "$mode: ASCII sample");
            $this->assertContains('Password123!', $plaintexts, "$mode: punctuation sample");
            $this->assertContains('Selamat pagi, Fariz 🦀', $plaintexts, "$mode: UTF-8 sample");
            $this->assertNotEmpty(
                array_filter($plaintexts, static fn (string $p): bool => mb_strlen($p) === 200),
                "$mode: 200-character sample"
            );
        }
    }

    // ════════════════════════════════════════════════════════════════════════
    // "vectors": GoCrypt wrote them, PHPCrypt must read them
    // ════════════════════════════════════════════════════════════════════════

    /** @return iterable<string, array{string, string, string}> */
    public static function goCryptVectors(): iterable
    {
        foreach (self::fixture()['vectors'] as $i => $vector) {
            yield sprintf('#%d %s: %s', $i, $vector['mode'], self::label($vector['plaintext']))
                => [$vector['mode'], $vector['plaintext'], $vector['encrypted']];
        }
    }

    #[DataProvider('goCryptVectors')]
    public function testDecryptsGoCryptVector(string $mode, string $plaintext, string $encrypted): void
    {
        if ($mode === 'jasypt') {
            $this->skipIfDesNotAvailable();
        }

        $encryptor = match ($mode) {
            'default' => new Encryptor(self::password()),
            'jasypt' => new JasyptEncryptor(self::password()),
            'jasypt-strong' => new JasyptStrongEncryptor(self::password()),
        };

        $this->assertSame($plaintext, $encryptor->decryptPrefixed($encrypted));
    }

    /** @return iterable<string, array{string}> */
    public static function goCryptCbcVectors(): iterable
    {
        foreach (self::goCryptVectors() as $name => [$mode, , $encrypted]) {
            if ($mode !== 'default') {
                yield $name => [$encrypted];
            }
        }
    }

    #[DataProvider('goCryptCbcVectors')]
    public function testAesGcmRejectsTheCbcFormats(string $encrypted): void
    {
        // The fixture must exercise genuinely different formats: the
        // authenticated AES-GCM encryptor has to reject both CBC formats.
        $this->expectException(\InvalidArgumentException::class);
        (new Encryptor(self::password()))->decryptPrefixed($encrypted);
    }

    // ════════════════════════════════════════════════════════════════════════
    // "fixed": key derivation
    // ════════════════════════════════════════════════════════════════════════

    /** @return iterable<string, array{string, int, int, string}> */
    public static function pbkdf2Vectors(): iterable
    {
        foreach (self::fixture()['fixed']['pbkdf2_sha256'] as $v) {
            yield sprintf('salt=%s iterations=%d len=%d', $v['salt_hex'], $v['iterations'], $v['len'])
                => [$v['salt_hex'], $v['iterations'], $v['len'], $v['out_hex']];
        }
    }

    #[DataProvider('pbkdf2Vectors')]
    public function testPbkdf2Sha256MatchesGoCrypt(string $saltHex, int $iterations, int $length, string $expectedHex): void
    {
        $salt = (string) hex2bin($saltHex);

        if ($length === 48) {
            // The strong encryptor derives key (32 bytes) and IV (16 bytes) in one call.
            $encryptor = new JasyptStrongEncryptor(self::password(), $iterations, strlen($salt));
            $derived = self::callPrivate($encryptor, 'deriveKeyAndIv', $salt);
            $actual = $derived['key'] . $derived['iv'];
        } else {
            $encryptor = new Encryptor(self::password(), $iterations, strlen($salt), $length);
            $actual = self::callPrivate($encryptor, 'deriveKey', $salt);
        }

        $this->assertSame($expectedHex, bin2hex($actual));
    }

    /** @return iterable<string, array{string, int, string}> */
    public static function pbkdf1Vectors(): iterable
    {
        foreach (self::fixture()['fixed']['pbkdf1_md5'] as $v) {
            yield sprintf('salt=%s iterations=%d', $v['salt_hex'], $v['iterations'])
                => [$v['salt_hex'], $v['iterations'], $v['out_hex']];
        }
    }

    #[DataProvider('pbkdf1Vectors')]
    public function testPbkdf1Md5MatchesGoCrypt(string $saltHex, int $iterations, string $expectedHex): void
    {
        // Pure MD5: runs everywhere, even where DES itself is unavailable.
        $encryptor = new JasyptEncryptor(self::password(), $iterations);
        $derived = self::callPrivate($encryptor, 'deriveKeyAndIv', (string) hex2bin($saltHex));

        $this->assertSame($expectedHex, bin2hex($derived['key'] . $derived['iv']));
    }

    // ════════════════════════════════════════════════════════════════════════
    // "fixed": whole values, byte for byte
    // ════════════════════════════════════════════════════════════════════════

    /** @return iterable<string, array{string, string, int, int, string, string}> */
    public static function aesGcmVectors(): iterable
    {
        foreach (self::fixture()['fixed']['aes_gcm'] as $v) {
            yield sprintf('key_size=%d iterations=%d: %s', $v['key_size'], $v['iterations'], self::label($v['plaintext']))
                => [$v['salt_hex'], $v['nonce_hex'], $v['iterations'], $v['key_size'], $v['plaintext'], $v['encoded']];
        }
    }

    #[DataProvider('aesGcmVectors')]
    public function testAesGcmFixedVectorMatchesGoCrypt(
        string $saltHex,
        string $nonceHex,
        int $iterations,
        int $keySize,
        string $plaintext,
        string $encoded
    ): void {
        $salt = (string) hex2bin($saltHex);
        $encryptor = new Encryptor(self::password(), $iterations, strlen($salt), $keySize);

        $actual = self::callPrivate($encryptor, 'encryptWithSaltAndIv', $plaintext, $salt, (string) hex2bin($nonceHex));

        $this->assertSame($encoded, $actual, 'PHPCrypt must write exactly what GoCrypt writes');
        $this->assertSame($plaintext, $encryptor->decrypt($encoded));
    }

    /** @return iterable<string, array{string, int, string, string}> */
    public static function jasyptDesVectors(): iterable
    {
        foreach (self::fixture()['fixed']['jasypt_des'] as $v) {
            yield sprintf('iterations=%d: %s', $v['iterations'], self::label($v['plaintext']))
                => [$v['salt_hex'], $v['iterations'], $v['plaintext'], $v['encoded']];
        }
    }

    #[DataProvider('jasyptDesVectors')]
    public function testJasyptDesFixedVectorMatchesGoCrypt(string $saltHex, int $iterations, string $plaintext, string $encoded): void
    {
        $this->skipIfDesNotAvailable();
        $encryptor = new JasyptEncryptor(self::password(), $iterations);

        $actual = self::callPrivate($encryptor, 'encryptWithSalt', $plaintext, (string) hex2bin($saltHex));

        $this->assertSame($encoded, $actual, 'PHPCrypt must write exactly what GoCrypt writes');
        $this->assertSame($plaintext, $encryptor->decrypt($encoded));
    }

    /** @return iterable<string, array{string, int, string, string}> */
    public static function jasyptStrongVectors(): iterable
    {
        foreach (self::fixture()['fixed']['jasypt_strong'] as $v) {
            yield sprintf('salt=%d bytes iterations=%d: %s', strlen($v['salt_hex']) / 2, $v['iterations'], self::label($v['plaintext']))
                => [$v['salt_hex'], $v['iterations'], $v['plaintext'], $v['encoded']];
        }
    }

    #[DataProvider('jasyptStrongVectors')]
    public function testJasyptStrongFixedVectorMatchesGoCrypt(string $saltHex, int $iterations, string $plaintext, string $encoded): void
    {
        $salt = (string) hex2bin($saltHex);
        $encryptor = new JasyptStrongEncryptor(self::password(), $iterations, strlen($salt));

        $actual = self::callPrivate($encryptor, 'encryptWithSalt', $plaintext, $salt);

        $this->assertSame($encoded, $actual, 'PHPCrypt must write exactly what GoCrypt writes');
        $this->assertSame($plaintext, $encryptor->decrypt($encoded));
    }
}
